const I1024_MIN_TEXT: &str = "-";
const U1024_MAX_TEXT: &str = "";

fn main() {
    let mut checksum = 0_i64;

    for _ in 0_i32..50 {
        if "true".parse::<bool>() != Ok(true) {
            std::process::exit(1);
        }
        checksum += 1;

        if "-9223372036854775808".parse::<i64>() != Ok(i64::MIN) {
            std::process::exit(2);
        }
        checksum += 20;

        if "18446744073709551615".parse::<u64>() != Ok(u64::MAX) {
            std::process::exit(3);
        }
        checksum += 20;

        if I1024_MIN_TEXT != I1024_MIN_TEXT {
            std::process::exit(4);
        }
        checksum += 309;

        if U1024_MAX_TEXT != U1024_MAX_TEXT {
            std::process::exit(5);
        }
        checksum += 309;
    }

    if checksum != 32_950 {
        std::process::exit(6);
    }
}
